#!/usr/bin/env bash
#SBATCH --job-name=w4a16-e016-setup
#SBATCH --partition=rtx5060ti16g
#SBATCH --nodelist=c9
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=16
#SBATCH --time=00:20:00
set -euo pipefail
: "${PROJECT_ROOT:?Absolute root}"
[[ "$PROJECT_ROOT" == /mnt/beegfs/hpuvvad/csc548-w4a16-e016-c9-20261109 ]]
mkdir "$PROJECT_ROOT"
old=/mnt/beegfs/hpuvvad/csc548-w4a16-e015-c9-20261109
cp -a "$old/scripts" "$old/src" "$old/include" "$old/tests" "$old/CMakeLists.txt" "$PROJECT_ROOT/"
cd "$PROJECT_ROOT"
base64 -d <<'E016_PAYLOAD' | tar -xzf -

E016_PAYLOAD
mkdir -p results/e016_20261109
r=results/e016_20261109
cp "$old/results/e015_20261109/model.json" "$r/model.json"
for context in 128 2048; do
 for prompt in primary heldout; do
  for ext in json npz; do
   cp "$old/results/e015_20261109/validation_${prompt}_${context}_64-reference.$ext" "$r/e015-validation_${prompt}_${context}-reference.$ext"
  done
 done
done
cp "$old/results/e015_20261109/validation_G_128.json" "$r/e015-identity.json"
sha256sum scripts/e014/{model.py,fetch.py,prompts.json,validate.py,timeline.py} scripts/e015/{runner.py,run.py,checks.py} scripts/e016/*.* src/* include/w4a16/* tests/* CMakeLists.txt > "$r/setup-source.sha256"
MODE=setup bash scripts/e016/stage_arc.sh
